# nt351 (VMID 83) — Windows NT Workstation 3.51 on the ISA-only machine.
#   TCG/486/64 MiB, 480 MiB FAT16 IDE disk, ISA Cirrus, SB16, NE2000 at
#   0x300/IRQ9. VERBATIM launcher with conditional -loadvm golden. The disk is
#   deliberately below the legacy 504 MiB CHS boundary: a 1 GiB install reaches
#   the desktop during Setup but cannot cold-boot through isapc's 16-head BIOS.
# DISPLAY: accelerated Cirrus 1024x768x65536 colors (16bpp). The launcher pins
#   /opt/qemu-cirrusfix with patch 0004-cirrus-blt-rop1-fill.patch; the stock
#   QEMU drops source-independent row fills and corrupts scroll/window redraws.
#   Rebuild the pinned binary whenever the packaged QEMU version changes.
#   Program Manager and Main are maximized; dirty -> loadvm restores cleanly.
# POINTER: NT reads only the relative PS/2 mouse. Streamhost receives absolute
#   browser coordinates, homes the relative guest at an edge, then applies the
#   measured cursor_scale for 1:1 tracking. Recalibrate after a resolution or
#   mouse-control-panel change.
emit nt351 \
  --tile nt351 --vmid 83 --udp 54083 --pointer abs --input-backend dbus-rel \
  --cursor-scale 1.0 --cursor-off-x 0 --cursor-off-y 0 --audio on --fps 30 \
  --launcher-file "$T/nt351/qemu-streamhost.sh" \
  --env-append-file "$T/nt351/tile.env.fixture"

